  nav_features: "Funções", nav_shots: "Capturas", nav_how: "Como funciona", nav_faq: "Perguntas", nav_download: "Descarregar grátis",
  lang_label: "Idioma",
  hero_tag: "Scraper de ROMs para Batocera Linux",
  hero_title: "A tua coleção retro, com capas, logótipos, vídeos e fichas.",
