  btn_download: "Descarregar grátis", btn_how: "Como funciona",
  badge_free: "100 % gratuito", badge_os: "Windows e Linux", badge_langs: "7 idiomas", badge_systems: "256 sistemas do Batocera",
  stats_visits: "Visitas ao site", stats_downloads: "Transferências", stats_win: "Windows", stats_linux: "Linux",
  stats_note: "As transferências são contadas em tempo real a partir do GitHub.",
